						metricValue = float64(sdata.Bounces)
						metricLabel = "ses_bounce_count"
						found = true

					case "ses_complaint_count":
						region := rule.SESRegion
						if region == "" {
							region = getEnv("AWS_REGION", "us-east-1")
						}
						cacheVal, ok := sesCache.Load(region)
						if !ok {
							continue
