func activityStatusUsesStoredBreakdown(conditions []int) bool {
	if len(conditions) == 0 {
		return false
	}
	for _, cond := range conditions {
		if cond != 1 && cond != 5 {
			return false
		}
	}
	return true
}

func normalizeStoredFailureStatusConditions(conditions []int) []int {
	if len(conditions) == 0 {
		return nil
	}
	seen := make(map[int]struct{})
	var out []int
	for _, cond := range conditions {
		if cond == -2 {
			return nil
		}
		if cond < 0 {
			continue
		}
		if _, ok := seen[cond]; ok {
			continue
		}
		seen[cond] = struct{}{}
		out = append(out, cond)
	}
	if len(out) == 0 {
		return []int{-999999}
	}
	sort.Ints(out)
	return out
}

