func alertRuleInCooldown(lastTriggeredAt *time.Time, cooldownSeconds int) bool {
	if cooldownSeconds <= 0 || lastTriggeredAt == nil {
		return false
	}
	return time.Since(*lastTriggeredAt) < time.Duration(cooldownSeconds)*time.Second
}

