		if err == sql.ErrNoRows {
			// Return default permissions for new users
			writeJSON(w, map[string]interface{}{
				"user_email":  currentEmail,
				"tenant_id":   tenantID,
				"role":        "user",
				"permissions": []string{},
			}, http.StatusOK)
