            className="alerts-input"
            placeholder="Search workflow type, error, workflow id..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            style={{ minWidth: 280, maxWidth: 420 }}
          />
        </div>

        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(auto-fit, minmax(160px, 1fr))",
            gap: 12,
            padding: "18px",
            borderBottom: "1px solid var(--separator)",
          }}
        >
          {[
            { label: "Triggered", value: summary.triggered },
            { label: "Skipped Duplicate", value: summary.skippedDuplicate },
            { label: "Trigger Failed", value: summary.failed },
          ].map((item) => (
            <div key={item.label} className="alerts-rule-card">
              <span className="alerts-detail-label">{item.label}</span>
              <span
                className="alerts-rule-name"
                style={{ marginTop: 8, display: "inline-block" }}
              >
                {item.value}
              </span>
            </div>
          ))}
        </div>

        {error && (
          <div className="error-banner">
            <span className="error-icon">!</span>
            <span>{error}</span>
          </div>
        )}

        {loading && (
          <div className="alerts-loading-inline">
            <div className="spinner" />
            <span>Loading Codefac workflow errors...</span>
          </div>
        )}

        {!loading && !error && filteredEvents.length === 0 && (
          <div className="alerts-empty">
            <p>No Codefac workflow error events found.</p>
          </div>
        )}

        {!loading && filteredEvents.length > 0 && (
          <div className="alerts-history-table-wrap">
            <table className="alerts-history-table">
              <thead>
                <tr>
                  <th>Timestamp</th>
                  <th>Pipeline</th>
                  <th>Decision</th>
                  <th>Workflow Type</th>
                  <th>Error</th>
                  <th>Workflow / Run</th>
                  <th>Duplicate Of</th>
                </tr>
              </thead>
              <tbody>
                {filteredEvents.map((event) => {
                  const tone = decisionTone(event.decision);
                  return (
                    <tr key={event.id}>
                      <td className="alerts-history-cell-time">
                        {formatTimestamp(event.created_at)}
                      </td>
                      <td style={{ fontSize: 12 }}>
                        <div>{event.pipeline_name || "Unknown pipeline"}</div>
                        {event.delivery_status && (
                          <div
                            style={{
                              fontSize: 11,
                              color: "var(--fg-tertiary)",
                              marginTop: 4,
                            }}
                          >
                            Delivery: {event.delivery_status}
                          </div>
                        )}
                      </td>
                      <td>
                        <span
                          style={{
                            display: "inline-block",
                            padding: "2px 8px",
                            borderRadius: 10,
                            fontSize: 10,
                            fontWeight: 600,
                            textTransform: "uppercase",
                            background: tone.background,
                            color: tone.color,
                          }}
                        >
                          {DECISION_LABELS[event.decision] || event.decision}
                        </span>
                      </td>
                      <td style={{ fontSize: 12 }}>
                        <code
                          style={{
                            fontSize: 10,
                            fontFamily: '"SF Mono", monospace',
                          }}
                        >
                          {event.workflow_type || "unknown"}
                        </code>
                      </td>
                      <td style={{ fontSize: 12, minWidth: 260 }}>
                        <div>{event.error_text || "Unknown error"}</div>
                        {event.error_message && (
                          <div
                            style={{
                              fontSize: 11,
                              color: "var(--danger, #d32f2f)",
                              marginTop: 4,
                            }}
                          >
                            {event.error_message}
                          </div>
                        )}
                      </td>
                      <td style={{ fontSize: 12 }}>
                        <div>
                          <code
                            style={{
                              fontSize: 10,
                              fontFamily: '"SF Mono", monospace',
                            }}
                          >
                            {event.workflow_id || "-"}
                          </code>
                        </div>
                        <div
                          style={{
                            marginTop: 4,
                            color: "var(--fg-tertiary)",
                            fontSize: 11,
                          }}
                        >
                          Run:{" "}
                          <code
                            style={{
                              fontSize: 10,
                              fontFamily: '"SF Mono", monospace',
                            }}
                          >
                            {event.run_id || "-"}
                          </code>
                        </div>
                      </td>
                      <td style={{ fontSize: 12 }}>
                        {event.duplicate_workflow_id ? (
                          <>
                            <div>
                              <code
                                style={{
                                  fontSize: 10,
                                  fontFamily: '"SF Mono", monospace',
                                }}
                              >
                                {event.duplicate_workflow_id}
                              </code>
                            </div>
                            <div
                              style={{
                                marginTop: 4,
                                color: "var(--fg-tertiary)",
                                fontSize: 11,
                              }}
                            >
                              Run:{" "}
                              <code
                                style={{
                                  fontSize: 10,
                                  fontFamily: '"SF Mono", monospace',
                                }}
                              >
                                {event.duplicate_run_id || "-"}
                              </code>
                            </div>
                            {event.duplicate_triggered_at && (
                              <div
                                style={{
                                  marginTop: 4,
                                  color: "var(--fg-tertiary)",
                                  fontSize: 11,
                                }}
                              >
                                Triggered at{" "}
                                {formatTimestamp(event.duplicate_triggered_at)}
                              </div>
                            )}
                          </>
                        ) : (
                          <span style={{ color: "var(--fg-tertiary)" }}>-</span>
                        )}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </section>
    </div>
  );
}

