    72	func initCodefacDedupeRedis(ctx context.Context) error {
    73		addr := strings.TrimSpace(getEnv("REDIS_ADDR", ""))
    74		if addr == "" {
    75			log.Printf("Codefac error dedupe: Redis disabled (REDIS_ADDR not set)")
    76			return nil
    77		}
    78	
    79		dbIndex := 0
    80		if rawDB := strings.TrimSpace(getEnv("REDIS_DB", "0")); rawDB != "" {
    81			parsed, err := strconv.Atoi(rawDB)
    82			if err != nil {
    83				return fmt.Errorf("parse REDIS_DB %q: %w", rawDB, err)
    84			}
    85			dbIndex = parsed
    86		}
    87	
    88		codefacDedupeRedisPrefix = strings.TrimSpace(getEnv("CODEFAC_ERROR_DEDUPE_REDIS_PREFIX", "codefac:error-dedupe"))
    89		if codefacDedupeRedisPrefix == "" {
    90			codefacDedupeRedisPrefix = "codefac:error-dedupe"
    91		}
    92	
    93		codefacDedupeRedisTTL = 0
    94		if rawTTL := strings.TrimSpace(getEnv("CODEFAC_ERROR_DEDUPE_TTL_SECONDS", "0")); rawTTL != "" {
    95			seconds, err := strconv.Atoi(rawTTL)
    96			if err != nil {
    97				return fmt.Errorf("parse CODEFAC_ERROR_DEDUPE_TTL_SECONDS %q: %w", rawTTL, err)
    98			}
    99			if seconds > 0 {
   100				codefacDedupeRedisTTL = time.Duration(seconds) * time.Second
   101			}
   102		}
   103	
   104		client := redis.NewClient(&redis.Options{
   105			Addr:     addr,
   106			Username: strings.TrimSpace(getEnv("REDIS_USERNAME", "")),
   107			Password: getEnv("REDIS_PASSWORD", ""),
   108			DB:       dbIndex,
   109		})
   110		if err := client.Ping(ctx).Err(); err != nil {
   111			return fmt.Errorf("ping redis: %w", err)
   112		}
   113	
   114		codefacDedupeRedisClient = client
   115		log.Printf("Codefac error dedupe: Redis enabled (addr=%s db=%d prefix=%s ttl=%s)", addr, dbIndex, codefacDedupeRedisPrefix, codefacDedupeRedisTTL)
   116		return nil
   117	}
