   138	func normalizeWorkflowErrorSignature(errorText string) string {
   139		trimmed := strings.TrimSpace(strings.ToLower(errorText))
   140		if trimmed == "" {
   141			trimmed = "unknown-error"
   142		}
   143		trimmed = strings.Join(strings.Fields(trimmed), " ")
   144		sum := sha256.Sum256([]byte(trimmed))
   145		return hex.EncodeToString(sum[:])
   146	}
