   226	func releaseCodefacWorkflowErrorLock(ctx context.Context, redisKey string, token string) {
   227		if !codefacDedupeEnabled() || token == "" {
   228			return
   229		}
   230		lockKey := codefacWorkflowErrorLockKey(redisKey)
   231		const script = `
   232	if redis.call("GET", KEYS[1]) == ARGV[1] then
   233		return redis.call("DEL", KEYS[1])
   234	end
   235	return 0
   236	`
   237		if err := codefacDedupeRedisClient.Eval(ctx, script, []string{lockKey}, token).Err(); err != nil && !errors.Is(err, redis.Nil) {
   238			log.Printf("WARN: codefac dedupe: release lock %s: %v", lockKey, err)
   239		}
   240	}
