   244			return nil
   245		}
   246		payload, err := json.Marshal(claim)
   247		if err != nil {
   248			return err
   249		}
   250		if codefacDedupeRedisTTL > 0 {
   251			return codefacDedupeRedisClient.Set(ctx, redisKey, payload, codefacDedupeRedisTTL).Err()
   252		}
   253		return codefacDedupeRedisClient.Set(ctx, redisKey, payload, 0).Err()
   254	}
