		}
	}

	rows, err := db.Query(`
		SELECT
			id, tenant_id, pipeline_id, pipeline_name, workflow_id, run_id, workflow_type,
			error_signature, error_text, decision, delivery_status, error_message,
			duplicate_workflow_id, duplicate_run_id, duplicate_triggered_at, created_at
		FROM codefac_workflow_error_events
		WHERE tenant_id = $1
		ORDER BY created_at DESC, id DESC
		LIMIT $2 OFFSET $3`,
		tenantID, limit, offset,
	)
	if err != nil {
		writeJSONError(w, fmt.Sprintf("list codefac workflow errors: %v", err), http.StatusInternalServerError)
