const (
	codefacWorkflowErrorDecisionTriggered        = "triggered"
	codefacWorkflowErrorDecisionTriggerFailed    = "trigger_failed"
	codefacWorkflowErrorDecisionSkippedDuplicate = "skipped_duplicate"
	codefacWorkflowErrorDecisionSkippedInflight  = "skipped_inflight"
	codefacWorkflowErrorStateProcessing          = "processing"
	codefacWorkflowErrorStateTriggered           = "triggered"
	codefacWorkflowErrorStaleAfter               = 5 * time.Minute
)

type codefacWorkflowErrorDetails struct {
	Text      string
	Signature string
}

type pipelineWorkflowErrorState struct {
	ID                 int
	TenantID           int
	PipelineID         int
	PipelineName       string
	WorkflowType       string
	ErrorSignature     string
	ErrorText          string
	State              string
	FirstWorkflowID    string
	FirstRunID         string
	FirstTriggeredAt   *time.Time
	LastWorkflowID     string
	LastRunID          string
	LastSeenAt         time.Time
	ProcessingStartedAt *time.Time
	UpdatedAt          time.Time
}

type codefacWorkflowErrorEvent struct {
	ID                   int        `json:"id"`
	TenantID             int        `json:"tenant_id"`
	PipelineID           int        `json:"pipeline_id"`
	PipelineName         string     `json:"pipeline_name"`
	WorkflowID           string     `json:"workflow_id"`
	RunID                string     `json:"run_id"`
	WorkflowType         string     `json:"workflow_type"`
	ErrorSignature       string     `json:"error_signature"`
	ErrorText            string     `json:"error_text"`
	Decision             string     `json:"decision"`
	DeliveryStatus       string     `json:"delivery_status"`
	ErrorMessage         string     `json:"error_message"`
	DuplicateWorkflowID  string     `json:"duplicate_workflow_id"`
	DuplicateRunID       string     `json:"duplicate_run_id"`
	DuplicateTriggeredAt *time.Time `json:"duplicate_triggered_at"`
	CreatedAt            time.Time  `json:"created_at"`
}

type codefacWorkflowErrorAcquireResult struct {
	Acquired bool
	Existing *pipelineWorkflowErrorState
}

func normalizeWorkflowErrorSignature(errorText string) string {
	trimmed := strings.TrimSpace(strings.ToLower(errorText))
	if trimmed == "" {
		return ""
	}
	trimmed = strings.Join(strings.Fields(trimmed), " ")
	sum := sha256.Sum256([]byte(trimmed))
	return hex.EncodeToString(sum[:])
}

func loadStoredWorkflowFailureText(ctx context.Context, tenantID int, workflowID string, runID string) (string, error) {
	var reason string
	var message string
	var details string
	var fetchError string
	var closeStatus int
	err := db.QueryRowContext(ctx, `
		SELECT
			COALESCE(NULLIF(failure_reason, ''), '') AS failure_reason,
			COALESCE(NULLIF(failure_message, ''), '') AS failure_message,
			COALESCE(NULLIF(failure_details, ''), '') AS failure_details,
			COALESCE(NULLIF(history_fetch_error, ''), '') AS history_fetch_error,
			close_status
		FROM workflow_failures
		WHERE tenant_id = $1 AND workflow_id = $2 AND run_id = $3`,
		tenantID, workflowID, runID,
	).Scan(&reason, &message, &details, &fetchError, &closeStatus)
	if errors.Is(err, sql.ErrNoRows) {
		return "", nil
	}
	if err != nil {
		return "", err
	}
	return storedActivityErrorText(reason, message, details, fetchError, workflowCloseStatusLabel(closeStatus)), nil
}

func workflowFailureErrorDetails(ctx context.Context, tenantID int, wf RecentWorkflow) codefacWorkflowErrorDetails {
	signatureText := strings.TrimSpace(wf.FailureReason)
	if signatureText == "" {
		storedText, err := loadStoredWorkflowFailureText(ctx, tenantID, wf.WorkflowID, wf.RunID)
		if err != nil {
			log.Printf("WARN: pipeline dedupe: load stored failure text tenant=%d workflow=%s run=%s: %v", tenantID, wf.WorkflowID, wf.RunID, err)
		} else {
			signatureText = strings.TrimSpace(storedText)
		}
	}

	displayText := signatureText
	if displayText == "" {
		displayText = strings.TrimSpace(wf.Status)
	}
	if displayText == "" {
		displayText = "Unknown error"
	}

	return codefacWorkflowErrorDetails{
		Text:      displayText,
		Signature: normalizeWorkflowErrorSignature(signatureText),
	}
}

func EnsurePipelineWorkflowErrorStateTable(db *sql.DB) error {
	query := `
	CREATE TABLE IF NOT EXISTS pipeline_workflow_error_state (
		id SERIAL PRIMARY KEY,
		tenant_id INTEGER NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
		pipeline_id INTEGER NOT NULL REFERENCES codefac_pipelines(id) ON DELETE CASCADE,
		pipeline_name TEXT NOT NULL DEFAULT '',
		workflow_type TEXT NOT NULL DEFAULT '',
		error_signature TEXT NOT NULL DEFAULT '',
		error_text TEXT NOT NULL DEFAULT '',
		state TEXT NOT NULL DEFAULT 'processing',
		first_workflow_id TEXT NOT NULL DEFAULT '',
		first_run_id TEXT NOT NULL DEFAULT '',
		first_triggered_at TIMESTAMPTZ,
		last_workflow_id TEXT NOT NULL DEFAULT '',
		last_run_id TEXT NOT NULL DEFAULT '',
		last_seen_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
		processing_started_at TIMESTAMPTZ,
		updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
		UNIQUE (tenant_id, pipeline_id, workflow_type, error_signature)
	);`
	if _, err := db.Exec(query); err != nil {
		return fmt.Errorf("create pipeline_workflow_error_state table: %w", err)
	}

	indexes := []string{
		`CREATE INDEX IF NOT EXISTS idx_pipeline_workflow_error_state_tenant_pipeline ON pipeline_workflow_error_state (tenant_id, pipeline_id, updated_at DESC)`,
		`CREATE INDEX IF NOT EXISTS idx_pipeline_workflow_error_state_lookup ON pipeline_workflow_error_state (tenant_id, workflow_type, error_signature)`,
	}
	for _, stmt := range indexes {
		if _, err := db.Exec(stmt); err != nil {
			log.Printf("WARN: could not ensure pipeline_workflow_error_state index %q: %v", stmt, err)
		}
	}
	return nil
}

