func scanPipelineWorkflowErrorState(row scanner) (*pipelineWorkflowErrorState, error) {
	var state pipelineWorkflowErrorState
	err := row.Scan(
		&state.ID,
		&state.TenantID,
		&state.PipelineID,
		&state.PipelineName,
		&state.WorkflowType,
		&state.ErrorSignature,
		&state.ErrorText,
		&state.State,
		&state.FirstWorkflowID,
		&state.FirstRunID,
		&state.FirstTriggeredAt,
		&state.LastWorkflowID,
		&state.LastRunID,
		&state.LastSeenAt,
		&state.ProcessingStartedAt,
		&state.UpdatedAt,
	)
	if err != nil {
		return nil, err
	}
	return &state, nil
}

type scanner interface {
	Scan(dest ...any) error
}

func getPipelineWorkflowErrorState(ctx context.Context, tenantID int, pipelineID int, workflowType string, errorSignature string) (*pipelineWorkflowErrorState, error) {
	row := db.QueryRowContext(ctx, `
		SELECT
			id, tenant_id, pipeline_id, pipeline_name, workflow_type, error_signature, error_text,
			state, first_workflow_id, first_run_id, first_triggered_at,
			last_workflow_id, last_run_id, last_seen_at, processing_started_at, updated_at
		FROM pipeline_workflow_error_state
		WHERE tenant_id = $1 AND pipeline_id = $2 AND workflow_type = $3 AND error_signature = $4`,
		tenantID, pipelineID, workflowType, errorSignature,
	)
	state, err := scanPipelineWorkflowErrorState(row)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	return state, nil
}

func tryAcquirePipelineWorkflowErrorState(
	ctx context.Context,
	tenantID int,
	pipe CodefacPipeline,
	wf RecentWorkflow,
	errorDetails codefacWorkflowErrorDetails,
) (codefacWorkflowErrorAcquireResult, error) {
	if errorDetails.Signature == "" {
		return codefacWorkflowErrorAcquireResult{Acquired: true}, nil
	}

	var state pipelineWorkflowErrorState
	row := db.QueryRowContext(ctx, `
		INSERT INTO pipeline_workflow_error_state (
			tenant_id, pipeline_id, pipeline_name, workflow_type, error_signature, error_text,
			state, first_workflow_id, first_run_id, last_workflow_id, last_run_id,
			last_seen_at, processing_started_at, updated_at
		)
		VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9, $8, $9, NOW(), NOW(), NOW())
		ON CONFLICT (tenant_id, pipeline_id, workflow_type, error_signature) DO NOTHING
		RETURNING
			id, tenant_id, pipeline_id, pipeline_name, workflow_type, error_signature, error_text,
			state, first_workflow_id, first_run_id, first_triggered_at,
			last_workflow_id, last_run_id, last_seen_at, processing_started_at, updated_at`,
		tenantID,
		pipe.ID,
		pipe.Name,
		wf.WorkflowType,
		errorDetails.Signature,
		errorDetails.Text,
		codefacWorkflowErrorStateProcessing,
		wf.WorkflowID,
		wf.RunID,
	)
	if scanned, err := scanPipelineWorkflowErrorState(row); err == nil {
		return codefacWorkflowErrorAcquireResult{Acquired: true, Existing: scanned}, nil
	} else if !errors.Is(err, sql.ErrNoRows) {
		return codefacWorkflowErrorAcquireResult{}, err
	}

	existing, err := getPipelineWorkflowErrorState(ctx, tenantID, pipe.ID, wf.WorkflowType, errorDetails.Signature)
	if err != nil {
		return codefacWorkflowErrorAcquireResult{}, err
	}
	if existing == nil {
		return codefacWorkflowErrorAcquireResult{Acquired: true}, nil
	}

	if existing.State == codefacWorkflowErrorStateProcessing &&
		existing.ProcessingStartedAt != nil &&
		time.Since(existing.ProcessingStartedAt.UTC()) > codefacWorkflowErrorStaleAfter {
		row = db.QueryRowContext(ctx, `
			UPDATE pipeline_workflow_error_state
			SET
				pipeline_name = $2,
				error_text = $3,
				state = $4,
				first_workflow_id = $5,
				first_run_id = $6,
				last_workflow_id = $5,
				last_run_id = $6,
				last_seen_at = NOW(),
				processing_started_at = NOW(),
				updated_at = NOW()
			WHERE id = $1
			  AND state = $4
			  AND processing_started_at IS NOT NULL
			  AND processing_started_at < NOW() - ($7::text || ' seconds')::interval
			RETURNING
				id, tenant_id, pipeline_id, pipeline_name, workflow_type, error_signature, error_text,
				state, first_workflow_id, first_run_id, first_triggered_at,
				last_workflow_id, last_run_id, last_seen_at, processing_started_at, updated_at`,
			existing.ID,
			pipe.Name,
			errorDetails.Text,
			codefacWorkflowErrorStateProcessing,
			wf.WorkflowID,
			wf.RunID,
			int(codefacWorkflowErrorStaleAfter.Seconds()),
		)
		if staleReplacement, err := scanPipelineWorkflowErrorState(row); err == nil {
			return codefacWorkflowErrorAcquireResult{Acquired: true, Existing: staleReplacement}, nil
		} else if !errors.Is(err, sql.ErrNoRows) {
			return codefacWorkflowErrorAcquireResult{}, err
		}
		existing, err = getPipelineWorkflowErrorState(ctx, tenantID, pipe.ID, wf.WorkflowType, errorDetails.Signature)
		if err != nil {
			return codefacWorkflowErrorAcquireResult{}, err
		}
	}

	return codefacWorkflowErrorAcquireResult{Acquired: false, Existing: existing}, nil
}

func markPipelineWorkflowErrorTriggered(
	ctx context.Context,
	tenantID int,
	pipe CodefacPipeline,
	wf RecentWorkflow,
	errorDetails codefacWorkflowErrorDetails,
	now time.Time,
) error {
	if errorDetails.Signature == "" {
		return nil
	}
	_, err := db.ExecContext(ctx, `
		UPDATE pipeline_workflow_error_state
		SET
			pipeline_name = $5,
			error_text = $6,
			state = $7,
			first_triggered_at = COALESCE(first_triggered_at, $8),
			last_workflow_id = $3,
			last_run_id = $4,
			last_seen_at = $8,
			processing_started_at = NULL,
			updated_at = $8
		WHERE tenant_id = $1 AND pipeline_id = $2 AND workflow_type = $9 AND error_signature = $10`,
		tenantID,
		pipe.ID,
		wf.WorkflowID,
		wf.RunID,
		pipe.Name,
		errorDetails.Text,
		codefacWorkflowErrorStateTriggered,
		now,
		wf.WorkflowType,
		errorDetails.Signature,
	)
	return err
}

func releasePipelineWorkflowErrorState(
	ctx context.Context,
	tenantID int,
	pipelineID int,
	workflowType string,
	errorSignature string,
) error {
	if errorSignature == "" {
		return nil
	}
	_, err := db.ExecContext(ctx, `
		DELETE FROM pipeline_workflow_error_state
		WHERE tenant_id = $1 AND pipeline_id = $2 AND workflow_type = $3 AND error_signature = $4
		  AND state = $5`,
		tenantID, pipelineID, workflowType, errorSignature, codefacWorkflowErrorStateProcessing,
	)
	return err
}

func touchPipelineWorkflowErrorState(
	ctx context.Context,
	state *pipelineWorkflowErrorState,
	wf RecentWorkflow,
) error {
	if state == nil || state.ID <= 0 {
		return nil
	}
	_, err := db.ExecContext(ctx, `
		UPDATE pipeline_workflow_error_state
		SET
			last_workflow_id = $2,
			last_run_id = $3,
			last_seen_at = NOW(),
			updated_at = NOW()
		WHERE id = $1`,
		state.ID, wf.WorkflowID, wf.RunID,
	)
	return err
}

