func markPipelineWorkflowErrorTriggered(
	ctx context.Context,
	tenantID int,
	pipe CodefacPipeline,
	wf RecentWorkflow,
	errorDetails pipelineWorkflowErrorDetails,
	now time.Time,
) error {
	if errorDetails.Signature == "" {
		return nil
	}
	_, err := db.ExecContext(ctx, `
		UPDATE pipeline_workflow_error_state
		SET
			pipeline_name = $5,
			error_text = $6,
			state = $7,
			first_triggered_at = COALESCE(first_triggered_at, $8),
			last_workflow_id = $3,
			last_run_id = $4,
			last_seen_at = $8,
			processing_started_at = NULL,
			updated_at = $8
		WHERE tenant_id = $1 AND pipeline_id = $2 AND workflow_type = $9 AND error_signature = $10`,
		tenantID,
		pipe.ID,
		wf.WorkflowID,
		wf.RunID,
		pipe.Name,
		errorDetails.Text,
		pipelineWorkflowErrorStateTriggered,
		now,
		wf.WorkflowType,
		errorDetails.Signature,
	)
	return err
}

func releasePipelineWorkflowErrorState(
	ctx context.Context,
	tenantID int,
	pipelineID int,
	workflowType string,
	errorSignature string,
) error {
	if errorSignature == "" {
		return nil
	}
	_, err := db.ExecContext(ctx, `
		DELETE FROM pipeline_workflow_error_state
		WHERE tenant_id = $1 AND pipeline_id = $2 AND workflow_type = $3 AND error_signature = $4
		  AND state = $5`,
		tenantID, pipelineID, workflowType, errorSignature, pipelineWorkflowErrorStateProcessing,
	)
	return err
}

func touchPipelineWorkflowErrorState(
	ctx context.Context,
	state *pipelineWorkflowErrorState,
	wf RecentWorkflow,
) error {
	if state == nil || state.ID <= 0 {
		return nil
	}
	_, err := db.ExecContext(ctx, `
		UPDATE pipeline_workflow_error_state
		SET
			last_workflow_id = $2,
			last_run_id = $3,
			last_seen_at = NOW(),
			updated_at = NOW()
		WHERE id = $1`,
		state.ID, wf.WorkflowID, wf.RunID,
	)
	return err
}

