func tryAcquirePipelineWorkflowErrorState(
	ctx context.Context,
	tenantID int,
	pipe CodefacPipeline,
	wf RecentWorkflow,
	errorDetails pipelineWorkflowErrorDetails,
) (pipelineWorkflowErrorAcquireResult, error) {
	if errorDetails.Signature == "" {
		return pipelineWorkflowErrorAcquireResult{Acquired: true}, nil
	}

	row := db.QueryRowContext(ctx, `
		INSERT INTO pipeline_workflow_error_state (
			tenant_id, pipeline_id, pipeline_name, workflow_type, error_signature, error_text,
			state, first_workflow_id, first_run_id, last_workflow_id, last_run_id,
			last_seen_at, processing_started_at, updated_at
		)
		VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9, $8, $9, NOW(), NOW(), NOW())
		ON CONFLICT (tenant_id, pipeline_id, workflow_type, error_signature) DO NOTHING
		RETURNING
			id, tenant_id, pipeline_id, pipeline_name, workflow_type, error_signature, error_text,
			state, first_workflow_id, first_run_id, first_triggered_at,
			last_workflow_id, last_run_id, last_seen_at, processing_started_at, updated_at`,
		tenantID,
		pipe.ID,
		pipe.Name,
		wf.WorkflowType,
		errorDetails.Signature,
		errorDetails.Text,
		pipelineWorkflowErrorStateProcessing,
		wf.WorkflowID,
		wf.RunID,
	)
	if scanned, err := scanPipelineWorkflowErrorState(row); err == nil {
		return pipelineWorkflowErrorAcquireResult{Acquired: true, Existing: scanned}, nil
	} else if !errors.Is(err, sql.ErrNoRows) {
		return pipelineWorkflowErrorAcquireResult{}, err
	}

	existing, err := getPipelineWorkflowErrorState(ctx, tenantID, pipe.ID, wf.WorkflowType, errorDetails.Signature)
	if err != nil {
		return pipelineWorkflowErrorAcquireResult{}, err
	}
	if existing == nil {
		return pipelineWorkflowErrorAcquireResult{Acquired: true}, nil
	}

	if existing.State == pipelineWorkflowErrorStateProcessing &&
		existing.ProcessingStartedAt != nil &&
		time.Since(existing.ProcessingStartedAt.UTC()) > pipelineWorkflowErrorStaleAfter {
		row = db.QueryRowContext(ctx, `
			UPDATE pipeline_workflow_error_state
			SET
				pipeline_name = $2,
				error_text = $3,
				state = $4,
				first_workflow_id = $5,
				first_run_id = $6,
				last_workflow_id = $5,
				last_run_id = $6,
				last_seen_at = NOW(),
				processing_started_at = NOW(),
				updated_at = NOW()
			WHERE id = $1
			  AND state = $4
			  AND processing_started_at IS NOT NULL
			  AND processing_started_at < NOW() - ($7 * INTERVAL '1 second')
			RETURNING
				id, tenant_id, pipeline_id, pipeline_name, workflow_type, error_signature, error_text,
				state, first_workflow_id, first_run_id, first_triggered_at,
				last_workflow_id, last_run_id, last_seen_at, processing_started_at, updated_at`,
			existing.ID,
			pipe.Name,
			errorDetails.Text,
			pipelineWorkflowErrorStateProcessing,
			wf.WorkflowID,
			wf.RunID,
			int(pipelineWorkflowErrorStaleAfter.Seconds()),
		)
		if staleReplacement, err := scanPipelineWorkflowErrorState(row); err == nil {
			return pipelineWorkflowErrorAcquireResult{Acquired: true, Existing: staleReplacement}, nil
		} else if !errors.Is(err, sql.ErrNoRows) {
			return pipelineWorkflowErrorAcquireResult{}, err
		}
		existing, err = getPipelineWorkflowErrorState(ctx, tenantID, pipe.ID, wf.WorkflowType, errorDetails.Signature)
		if err != nil {
			return pipelineWorkflowErrorAcquireResult{}, err
		}
	}

	return pipelineWorkflowErrorAcquireResult{Acquired: false, Existing: existing}, nil
}

