func pipelineWorkflowErrorsHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeJSONError(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	tenantIDStr := r.URL.Query().Get("tenant_id")
	if tenantIDStr == "" {
		writeJSONError(w, "missing tenant_id", http.StatusBadRequest)
		return
	}

	var tenantID int
	if _, err := fmt.Sscanf(tenantIDStr, "%d", &tenantID); err != nil || tenantID <= 0 {
		writeJSONError(w, "invalid tenant_id", http.StatusBadRequest)
		return
	}

	limit := 200
	if raw := strings.TrimSpace(r.URL.Query().Get("limit")); raw != "" {
		if parsed, err := strconv.Atoi(raw); err == nil && parsed > 0 && parsed <= 1000 {
			limit = parsed
		}
	}

	offset := 0
	if raw := strings.TrimSpace(r.URL.Query().Get("offset")); raw != "" {
		if parsed, err := strconv.Atoi(raw); err == nil && parsed >= 0 {
			offset = parsed
		}
	}

	rows, err := db.Query(`
		SELECT
			id, tenant_id, pipeline_id, pipeline_name, workflow_id, run_id, workflow_type,
			error_signature, error_text, decision, delivery_status, error_message,
			duplicate_workflow_id, duplicate_run_id, duplicate_triggered_at, created_at
		FROM pipeline_workflow_error_events
		WHERE tenant_id = $1
		ORDER BY created_at DESC, id DESC
		LIMIT $2 OFFSET $3`,
		tenantID, limit, offset,
	)
	if err != nil {
		writeJSONError(w, fmt.Sprintf("list pipeline workflow errors: %v", err), http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	events := make([]pipelineWorkflowErrorEvent, 0)
	for rows.Next() {
		var event pipelineWorkflowErrorEvent
		if err := rows.Scan(
			&event.ID,
			&event.TenantID,
			&event.PipelineID,
			&event.PipelineName,
			&event.WorkflowID,
			&event.RunID,
			&event.WorkflowType,
			&event.ErrorSignature,
			&event.ErrorText,
			&event.Decision,
			&event.DeliveryStatus,
			&event.ErrorMessage,
			&event.DuplicateWorkflowID,
			&event.DuplicateRunID,
			&event.DuplicateTriggeredAt,
			&event.CreatedAt,
		); err != nil {
			writeJSONError(w, fmt.Sprintf("scan pipeline workflow error event: %v", err), http.StatusInternalServerError)
			return
		}
		events = append(events, event)
	}
	if err := rows.Err(); err != nil {
		writeJSONError(w, fmt.Sprintf("iterate pipeline workflow errors: %v", err), http.StatusInternalServerError)
		return
	}

	writeJSON(w, map[string]any{
		"results": events,
		"limit":   limit,
		"offset":  offset,
	}, http.StatusOK)
}

