func markPipelineWorkflowFailureCooldown(
	ctx context.Context,
	row *pipelineWorkflowFailureRow,
	lastTriggeredAt *time.Time,
) error {
	if row == nil || row.ID <= 0 {
		return nil
	}
	var cooldownUntil any
	if lastTriggeredAt != nil {
		cooldownUntil = lastTriggeredAt.UTC().Format(time.RFC3339)
	} else {
		cooldownUntil = ""
	}
	_, err := db.ExecContext(ctx, `
		UPDATE pipeline_workflow_failures
		SET
			status = $2,
			delivery_status = 'skipped',
			error_message = $3,
			matched_failure_id = NULL,
			matched_workflow_id = '',
