import { useState, useEffect } from "react";
import { useAuth } from "../auth/AuthContext";
import "./NotificationsPage.css";

const FILTER_OPTIONS = [
  { key: "all", label: "All" },
  { key: "pending", label: "Pending" },
  { key: "processing", label: "Processing" },
  { key: "triggered", label: "Triggered" },
  { key: "skipped_duplicate", label: "Skipped Duplicate" },
  { key: "skipped_cooldown", label: "Skipped Cooldown" },
  { key: "trigger_failed", label: "Trigger Failed" },
  { key: "skipped_inflight", label: "Skipped Inflight" },
];

const STATUS_LABELS = {
  pending: "Pending",
  processing: "Processing",
  triggered: "Triggered",
  skipped_duplicate: "Skipped duplicate",
  skipped_cooldown: "Skipped cooldown",
  trigger_failed: "Trigger failed",
  skipped_inflight: "Skipped inflight",
};

function formatTimestamp(ts) {
  if (!ts) return "";
  try {
    const date = new Date(ts);
    if (Number.isNaN(date.getTime())) return ts;
    return date.toLocaleString();
  } catch {
    return ts;
  }
}

function statusTone(status) {
  switch (status) {
    case "pending":
    case "processing":
      return {
        background: "var(--surface-secondary)",
        color: "var(--fg-primary)",
      };
    case "triggered":
      return {
        background: "var(--accent-bg)",
        color: "var(--accent)",
      };
    case "skipped_duplicate":
    case "skipped_cooldown":
      return {
        background: "var(--warning-bg)",
        color: "var(--warning-fg)",
      };
    case "trigger_failed":
      return {
        background: "var(--danger-bg, #fce4e4)",
        color: "var(--danger, #d32f2f)",
      };
    default:
      return {
        background: "var(--surface-secondary)",
        color: "var(--fg-secondary)",
      };
  }
}

function PipelineErrorsPage({ selectedTenantId }) {
  const { authFetch } = useAuth();
  const [failures, setFailures] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [filter, setFilter] = useState("all");
  const [search, setSearch] = useState("");

  useEffect(() => {
    let cancelled = false;

    const run = async () => {
      if (!selectedTenantId) {
        if (!cancelled) {
          setFailures([]);
          setLoading(false);
        }
        return;
      }

      try {
        if (!cancelled) {
          setLoading(true);
          setError(null);
        }
        const res = await authFetch(
          `/api/codefac-pipeline?tenant_id=${selectedTenantId}&limit=200&offset=0`,
        );
        if (!res.ok) throw new Error(`HTTP error ${res.status}`);
        const json = await res.json();
        if (!cancelled) {
          setFailures(Array.isArray(json) ? json : (json.results ?? []));
        }
      } catch (err) {
        if (!cancelled) {
          setError(err.message);
        }
      } finally {
        if (!cancelled) {
          setLoading(false);
        }
      }
    };

    run();
    const timer = window.setInterval(run, 30000);
    return () => {
      cancelled = true;
      window.clearInterval(timer);
    };
  }, [authFetch, selectedTenantId]);

  const searchValue = search.trim().toLowerCase();
  const filteredFailures = failures.filter((failure) => {
    if (filter !== "all" && failure.status !== filter) {
      return false;
    }
    if (!searchValue) {
      return true;
    }
    return [
      failure.pipeline_name,
      failure.workflow_type,
      failure.workflow_id,
      failure.run_id,
      failure.error_text,
      failure.error_message,
      failure.matched_workflow_id,
      failure.matched_run_id,
    ]
      .filter(Boolean)
      .some((value) => String(value).toLowerCase().includes(searchValue));
  });

  const summary = failures.reduce(
    (acc, failure) => {
      if (failure.status === "triggered") acc.triggered += 1;
      if (failure.status === "skipped_duplicate") acc.skippedDuplicate += 1;
      if (failure.status === "skipped_cooldown") acc.skippedCooldown += 1;
      if (failure.status === "trigger_failed") acc.failed += 1;
      if (failure.status === "processing") acc.processing += 1;
      return acc;
    },
    {
      triggered: 0,
      skippedDuplicate: 0,
      skippedCooldown: 0,
      failed: 0,
      processing: 0,
    },
  );

  return (
    <div className="alerts-page">
      <section className="alerts-section card-surface">
        <div className="section-header">
          <div>
            <h2 className="section-title">Pipeline Errors</h2>
            <p className="section-subtitle">
              Track every failed workflow row, its current pipeline status, and
              which rows were skipped because the same workflow-type/error had
              already been handled.
            </p>
          </div>
        </div>

        <div
          className="failures-filters"
          style={{
            padding: "14px 18px",
            display: "flex",
            gap: "12px",
            alignItems: "center",
            flexWrap: "wrap",
            background: "var(--surface-secondary)",
            borderBottom: "1px solid var(--separator)",
          }}
        >
          <span className="filter-label">Status</span>
          {FILTER_OPTIONS.map((option) => (
            <button
              key={option.key}
              className={`filter-chip${filter === option.key ? " active" : ""}`}
              onClick={() => setFilter(option.key)}
            >
              {option.label}
            </button>
          ))}
          <input
            type="search"
            className="alerts-input"
            placeholder="Search workflow type, error, workflow id..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            style={{ minWidth: 280, maxWidth: 420 }}
          />
        </div>

        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(auto-fit, minmax(160px, 1fr))",
            gap: 12,
            padding: "18px",
            borderBottom: "1px solid var(--separator)",
          }}
        >
          {[
            { label: "Triggered", value: summary.triggered },
            { label: "Skipped Duplicate", value: summary.skippedDuplicate },
            { label: "Skipped Cooldown", value: summary.skippedCooldown },
            { label: "Trigger Failed", value: summary.failed },
            { label: "Processing", value: summary.processing },
          ].map((item) => (
            <div key={item.label} className="alerts-rule-card">
              <span className="alerts-detail-label">{item.label}</span>
              <span
                className="alerts-rule-name"
                style={{ marginTop: 8, display: "inline-block" }}
              >
                {item.value}
              </span>
            </div>
          ))}
        </div>

        {error && (
          <div className="error-banner">
            <span className="error-icon">!</span>
            <span>{error}</span>
          </div>
        )}

        {loading && (
          <div className="alerts-loading-inline">
            <div className="spinner" />
            <span>Loading pipeline errors...</span>
          </div>
        )}

        {!loading && !error && filteredFailures.length === 0 && (
          <div className="alerts-empty">
