                        </code>
                      </td>
                      <td style={{ fontSize: 12, minWidth: 260 }}>
                        <div>{failure.error_text || "Unknown error"}</div>
                        {failure.error_message && (
                          <div
                            style={{
                              fontSize: 11,
                              color: "var(--danger, #d32f2f)",
                              marginTop: 4,
                            }}
                          >
                            {failure.error_message}
                          </div>
                        )}
                      </td>
                      <td style={{ fontSize: 12 }}>
                        <div>
