import "./PipelineErrorsPage.css";

const FILTER_OPTIONS = [
  { key: "all", label: "All" },
  { key: "pending", label: "Pending" },
  { key: "processing", label: "Processing" },
  { key: "triggered", label: "Triggered" },
  { key: "skipped_duplicate", label: "Skipped Duplicate" },
  { key: "skipped_cooldown", label: "Skipped Cooldown" },
  { key: "trigger_failed", label: "Trigger Failed" },
  { key: "skipped_inflight", label: "Skipped Inflight" },
];

const STATUS_LABELS = {
  pending: "Pending",
  processing: "Processing",
  triggered: "Triggered",
  skipped_duplicate: "Skipped duplicate",
  skipped_cooldown: "Skipped cooldown",
  trigger_failed: "Trigger failed",
  skipped_inflight: "Skipped inflight",
};

const STATUS_DESCRIPTIONS = {
  pending: "Captured, waiting for evaluation",
  processing: "Currently being sent to the pipeline",
  triggered: "Delivered to the pipeline successfully",
  skipped_duplicate: "Same workflow type and error already triggered",
  skipped_cooldown: "Suppressed because pipeline cooldown is active",
  trigger_failed: "Pipeline delivery attempt failed",
  skipped_inflight: "Held because a matching request is still processing",
};

function formatTimestamp(ts) {
  if (!ts) return "";
  try {
    const date = new Date(ts);
    if (Number.isNaN(date.getTime())) return ts;
    return date.toLocaleString();
  } catch {
    return ts;
  }
}

function formatRelative(ts) {
  if (!ts) return "No activity yet";
  const then = new Date(ts).getTime();
  if (Number.isNaN(then)) return "Unknown";
  const diffMs = Date.now() - then;
  const absMs = Math.max(diffMs, 0);
  const minutes = Math.floor(absMs / 60000);
  if (minutes < 1) return "Just now";
  if (minutes < 60) return `${minutes}m ago`;
  const hours = Math.floor(minutes / 60);
  if (hours < 24) return `${hours}h ago`;
  const days = Math.floor(hours / 24);
  return `${days}d ago`;
}

function statusTone(status) {
  switch (status) {
    case "pending":
    case "processing":
      return {
        background: "var(--surface-secondary)",
        color: "var(--fg-primary)",
      };
    case "triggered":
      return {
        background: "var(--accent-bg)",
        color: "var(--accent)",
      };
    case "skipped_duplicate":
    case "skipped_cooldown":
      return {
        background: "var(--warning-bg)",
        color: "var(--warning-fg)",
      };
    case "trigger_failed":
      return {
        background: "var(--danger-bg, #fce4e4)",
        color: "var(--danger, #d32f2f)",
      };
    default:
      return {
        background: "var(--surface-secondary)",
        color: "var(--fg-secondary)",
      };
  }
}

function PipelineErrorsPage({ selectedTenantId }) {
  const { authFetch } = useAuth();
  const [failures, setFailures] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [filter, setFilter] = useState("all");
  const [search, setSearch] = useState("");

  useEffect(() => {
    let cancelled = false;

    const run = async () => {
      if (!selectedTenantId) {
        if (!cancelled) {
          setFailures([]);
          setLoading(false);
        }
        return;
      }

      try {
        if (!cancelled) {
          setLoading(true);
          setError(null);
        }
        const res = await authFetch(
          `/api/codefac-pipeline?tenant_id=${selectedTenantId}&limit=200&offset=0`,
        );
        if (!res.ok) throw new Error(`HTTP error ${res.status}`);
        const json = await res.json();
        if (!cancelled) {
          setFailures(Array.isArray(json) ? json : (json.results ?? []));
        }
      } catch (err) {
        if (!cancelled) {
          setError(err.message);
        }
      } finally {
        if (!cancelled) {
          setLoading(false);
        }
      }
    };

    run();
    const timer = window.setInterval(run, 30000);
    return () => {
      cancelled = true;
      window.clearInterval(timer);
    };
  }, [authFetch, selectedTenantId]);

