  useEffect(() => {
    const stored = localStorage.getItem(TOKEN_KEY);
    if (!stored) { setChecking(false); return; }

    fetch("/api/auth/me", { headers: { Authorization: `Bearer ${stored}` } })
      .then((r) => {
        if (!r.ok) throw new Error("expired");
        return r.json();
      })
