		}
		results = append(results, *item)
	}
	if err := rows.Err(); err != nil {
		writeJSONError(w, fmt.Sprintf("iterate pipeline workflow failures: %v", err), http.StatusInternalServerError)
		return
	}

	writeJSON(w, map[string]any{
		"results": results,
		"limit":   limit,
		"offset":  offset,
	}, http.StatusOK)
}

