    align-items: flex-start;
    gap: 20px;
    flex-wrap: wrap;
    background: var(--surface-secondary);
    border-bottom: 1px solid var(--separator);
}

/* ─── Tasklist dropdown ──────────────────────────────────────── */

.tl-dropdown-container {
    position: relative;
}

.tl-dropdown-trigger {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    height: var(--control-height);
    padding: 0 10px;
    border-radius: var(--radius-sm);
    border: 1px solid var(--border);
    background: var(--surface);
    color: var(--fg-secondary);
    font-size: 12px;
    font-weight: 500;
    cursor: pointer;
    transition:
        background 0.12s ease,
        border-color 0.12s ease,
        color 0.12s ease;
    white-space: nowrap;
    max-width: 220px;
}

.tl-dropdown-trigger:hover,
.tl-dropdown-trigger.open {
    background: var(--surface-secondary);
    color: var(--fg);
}

.tl-dropdown-trigger.has-selection {
    background: var(--accent-bg);
    color: var(--accent);
    border-color: transparent;
}

.tl-dropdown-label {
    flex: 1;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
}

.tl-dropdown-count {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 18px;
    height: 16px;
    padding: 0 5px;
    border-radius: 8px;
    background: var(--accent);
    color: #fff;
    font-size: 10px;
    font-weight: 700;
    flex-shrink: 0;
}

.tl-dropdown-chevron {
    flex-shrink: 0;
    color: var(--fg-tertiary);
    transition: transform 0.15s ease;
}

.tl-dropdown-chevron.open {
    transform: rotate(180deg);
}

.tl-dropdown-panel {
    position: absolute;
    top: calc(100% + 4px);
    left: 0;
    min-width: 240px;
    max-width: 340px;
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: var(--radius-md);
    box-shadow: var(--shadow-dropdown);
    z-index: 200;
    overflow: hidden;
}

.tl-dropdown-search {
    padding: 8px 8px 4px;
    border-bottom: 1px solid var(--separator);
}

.tl-dropdown-search input {
    width: 100%;
    height: var(--control-height);
    padding: 0 8px;
    border: 1px solid var(--border);
    border-radius: var(--radius-sm);
    background: var(--surface-secondary);
    color: var(--fg);
    font-size: 12px;
    outline: none;
    font-family: inherit;
}

.tl-dropdown-search input:focus {
    border-color: var(--accent);
}

.tl-dropdown-search input::placeholder {
    color: var(--fg-tertiary);
}

.tl-dropdown-list {
    max-height: 240px;
    overflow-y: auto;
    padding: 4px;
}

.tl-dropdown-item {
    display: flex;
    align-items: center;
    gap: 8px;
    height: 32px;
    padding: 0 8px;
    border-radius: var(--radius-sm);
    cursor: pointer;
    transition: background 0.1s ease;
    user-select: none;
}

.tl-dropdown-item:hover {
    background: var(--surface-secondary);
}

.tl-dropdown-item.checked {
    background: var(--accent-bg);
}

.tl-dropdown-item input[type="checkbox"] {
    width: 14px;
    height: 14px;
    accent-color: var(--accent);
    cursor: pointer;
    flex-shrink: 0;
}

.tl-dropdown-item-name {
    font-family: "SF Mono", "Menlo", "Monaco", monospace;
    font-size: 11.5px;
    color: var(--fg);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.tl-dropdown-item.checked .tl-dropdown-item-name {
    color: var(--accent);
    font-weight: 500;
}

.tl-dropdown-empty {
    padding: 20px;
    text-align: center;
    font-size: 12px;
    color: var(--fg-tertiary);
}

.tl-dropdown-footer {
    padding: 4px 8px 8px;
    border-top: 1px solid var(--separator);
}

.tl-dropdown-clear {
    width: 100%;
    height: 28px;
    border-radius: var(--radius-sm);
    border: 1px solid rgba(220, 53, 69, 0.2);
    background: var(--danger-bg);
    color: var(--danger-fg);
    font-size: 12px;
    font-weight: 500;
    cursor: pointer;
    font-family: inherit;
    transition: background 0.12s ease;
}

.tl-dropdown-clear:hover {
    background: rgba(220, 53, 69, 0.15);
}

.no-matches-cell {
    text-align: center !important;
    padding: 32px 16px !important;
    color: var(--fg-tertiary) !important;
    font-size: 13px !important;
}

.failures-empty {
    padding: 48px 20px;
    text-align: center;
    color: var(--fg-tertiary);
    font-size: 13px;
}

.empty-icon {
    font-size: 20px;
    color: var(--success);
    display: block;
    margin-bottom: 8px;
    opacity: 0.7;
}

.failures-empty p {
    font-size: 13px;
}

/* Pagination */

.pagination-controls {
    display: flex;
    align-items: center;
    gap: 5px;
}

.pagination-btn {
    display: inline-flex;
    align-items: center;
    height: var(--control-height);
    padding: 0 12px;
    border: 1px solid var(--border);
    border-radius: var(--radius-sm);
    font-size: 12px;
    font-weight: 500;
    font-family: inherit;
    background: var(--surface);
    color: var(--fg);
    cursor: pointer;
    transition:
        background 0.12s ease,
        border-color 0.12s ease;
}

